// noescape_probe_test.go is the soundness probe for pointer pinning across the
// Call funnel. It establishes, on ffi's real Call path, the exact boundary any
// wrapper that passes a Go-pointer buffer through the funnel must enforce:
//
//   - PINNED (sound): the caller pins buf with runtime.Pinner before the call and
//     unpins after. Pin forces the object to the heap (its argument escapes) and
//     pins it there, so the laundered uintptr stays valid across the synchronous C
//     write. This must be corruption-free under aggressive GC and stack movement.
//     A //go:uintptrescapes wrapper (what the calls/ package emits) is equivalent:
//     the call-site conversion escapes the object and keeps it alive for the call.
//
//   - KEEPALIVE-ONLY (unsound): laundering in-frame with only a trailing
//     runtime.KeepAlive prevents the object from being FREED, but not from
//     MOVING. If escape analysis leaves the object on the goroutine stack (a
//     uintptr conversion is not a reference, and KeepAlive does not force
//     escape), any stack growth or GC-driven stack move relocates it; the
//     laundered uintptr goes stale and the C write lands at the old address.
//     TestNoescapeProbe_KeepAliveOnlyUnsound proves this deterministically; in
//     the wild it surfaced as an intermittent CI failure (linux, GOMAXPROCS>=4,
//     ~40% of runs, identical under CGO_ENABLED=0 and =1).
//
//   - NAIVE (unsound): the pointer is laundered with NO guard at all, so the
//     object's only live reference is an integer the GC cannot see and it can be
//     reclaimed mid-call. TestNoescapeProbe_NaiveUnsafe demonstrates this half.
//
// The generator rule this pins: when a wrapper passes a Go-pointer buffer through
// the funnel, it MUST pin the buffer with a runtime.Pinner bracketing the call or
// be marked //go:uintptrescapes. A trailing KeepAlive alone is NOT sufficient —
// it is a liveness guard, not a movement guard.
//
// A note on writing these probes: escape analysis is static. A Pinner.Pin(buf)
// anywhere in a function forces buf to the heap on every path of that function,
// so the pinned and unpinned variants must live in separate functions or the
// unsound variant silently becomes heap-resident and stops demonstrating anything.

//go:build (amd64 || arm64) && (darwin || freebsd || linux || netbsd)

package ffi_test

import (
	"runtime"
	"testing"
	"unsafe"

	ffi "github.com/tmc/lib/nvidia/internal/ffi"
)

// srcWriteBuf writes a sentinel through a caller-provided buffer pointer, the
// canonical "C writes into a Go-owned buffer" shape.
const srcWriteBuf = `
#include <stdint.h>
void writebuf(int64_t *buf, int64_t val){ buf[0] = val; }`

// gcSpin runs a background goroutine that forces GC repeatedly until stopped, so
// any window in which a buffer is unreachable or movable is likely to be hit.
func gcSpin() (stop func()) {
	done := make(chan struct{})
	go func() {
		for {
			select {
			case <-done:
				return
			default:
				runtime.GC()
				_ = make([]byte, 1<<16)
			}
		}
	}()
	return func() { close(done) }
}

// callWriteBufPinned is the PINNED caller: pin, launder, call, unpin. This is the
// shape the generator must emit when it cannot use //go:uintptrescapes.
func callWriteBufPinned(fn uintptr, buf *int64, val int64) {
	var p runtime.Pinner
	p.Pin(buf)
	defer p.Unpin()
	var args [ffi.MaxArgs]uintptr
	args[0] = uintptr(unsafe.Pointer(buf))
	args[1] = uintptr(val)
	ffi.Call(fn, 2, &args, 0)
}

// The unsound KeepAlive-only shape is demonstrated inline in
// TestNoescapeProbe_KeepAliveOnlyUnsound: the hazard window opens at the
// uintptr conversion and closes when the C write consumes the address, so the
// demonstration must launder BEFORE the forced stack move. A wrapper that
// launders immediately before Call narrows that window to the interior of Call
// itself (stack growth in the dispatch prologue, or async preemption + GC stack
// move) but does not close it — that residual window is what CI hit
// intermittently at GOMAXPROCS>=4, ~40% of 300-run batches, identically under
// CGO_ENABLED=0 and =1.

// The stack-growth stress below reuses growStack from reentrant_deepnest_test.go.

// TestNoescapeProbe_PinnedStable asserts the sound path never corrupts: across
// many iterations under aggressive GC, the C write always lands and reads back.
func TestNoescapeProbe_PinnedStable(t *testing.T) {
	fn := buildSym(t, srcWriteBuf, "writebuf")
	stop := gcSpin()
	defer stop()
	for i := 0; i < 100000; i++ {
		buf := new(int64)
		callWriteBufPinned(fn, buf, int64(i))
		if got := *buf; got != int64(i) {
			t.Fatalf("iter %d: pinned path corrupted: got %d want %d", i, got, i)
		}
	}
}

// TestNoescapeProbe_KeepAliveOnlyUnsound proves deterministically WHY the
// KeepAlive-only pattern is rejected. Each iteration runs on a fresh goroutine
// (small initial stack), launders buf, then forces stack growth before the C
// write: the stack copy relocates buf, the laundered uintptr goes stale, and the
// write lands at the old address. Movement must predict corruption exactly; the
// pinned shape under the identical stack-growth stress must never move or corrupt.
// The two loops below are written out separately, calling each variant DIRECTLY:
// passing the variant as a func value would make buf escape at the indirect call
// site and neutralize the demonstration (the same static-escape gotcha the file
// comment describes).
func TestNoescapeProbe_KeepAliveOnlyUnsound(t *testing.T) {
	fn := buildSym(t, srcWriteBuf, "writebuf")

	moved, corrupted := 0, 0
	for i := 1; i <= 200; i++ {
		done := make(chan struct{})
		go func(val int64) {
			defer close(done)
			buf := new(int64) // must stay stack-resident: no Pin, no indirect calls
			var args [ffi.MaxArgs]uintptr
			args[0] = uintptr(unsafe.Pointer(buf)) //ffivet:ignore deliberate unsound launder: this test demonstrates the staleness ffivet rejects
			args[1] = uintptr(val)
			before := uintptr(unsafe.Pointer(buf))      //ffivet:ignore address snapshot for detecting the stack copy, never dereferenced
			growStack(64)                               // stack copy relocates buf; args[0] is now stale
			if uintptr(unsafe.Pointer(buf)) != before { //ffivet:ignore address comparison for detecting the stack copy, never dereferenced
				moved++
			}
			ffi.Call(fn, 2, &args, 0) // C writes through the stale address
			runtime.KeepAlive(buf)    // liveness only — cannot repair the stale word
			if *buf != val {
				corrupted++
			}
		}(int64(i))
		<-done
	}
	t.Logf("KeepAlive-only: moved=%d/200 corrupted=%d/200", moved, corrupted)
	if moved == 0 {
		t.Skip("stack never moved; mechanism not demonstrable on this configuration")
	}
	if corrupted != moved {
		t.Errorf("KeepAlive-only: moved (%d) != corrupted (%d); movement should exactly predict stale writes", moved, corrupted)
	}

	movedP, corruptedP := 0, 0
	for i := 1; i <= 200; i++ {
		done := make(chan struct{})
		go func(val int64) {
			defer close(done)
			buf := new(int64) // escapes: callWriteBufPinned pins its parameter
			before := uintptr(unsafe.Pointer(buf))
			growStack(64)
			if uintptr(unsafe.Pointer(buf)) != before {
				movedP++
			}
			callWriteBufPinned(fn, buf, val)
			if *buf != val {
				corruptedP++
			}
		}(int64(i))
		<-done
	}
	t.Logf("pinned control: moved=%d/200 corrupted=%d/200", movedP, corruptedP)
	if corruptedP != 0 {
		t.Errorf("pinned control corrupted %d/200 times; Pinner must make the launder sound", corruptedP)
	}
	if movedP != 0 {
		t.Errorf("pinned control moved %d/200 times; Pin must force heap residence", movedP)
	}
}

// TestNoescapeProbe_NaiveUnsafe demonstrates the LIVENESS half of the contract:
// with no guard at all, a laundered-only object can be reclaimed mid-call. A
// finalizer on the buffer flips a flag; if it fires while the "call" is in flight
// (the object was unreachable because only a uintptr referenced it), the naive
// path is proven unsafe. We model the liveness window directly rather than
// through a real C call, because relying on a crash is flaky. KeepAlive does fix
// THIS failure mode — it is necessary, just not sufficient (see
// TestNoescapeProbe_KeepAliveOnlyUnsound for the movement half that only
// Pinner/uintptrescapes covers).
func TestNoescapeProbe_NaiveUnsafe(t *testing.T) {
	stop := gcSpin()
	defer stop()

	// window models the in-flight C call: force a GC and let finalizers run.
	window := func() {
		runtime.GC()
		runtime.GC() // second cycle: first frees, finalizers queue; second lets them run
	}

	// NAIVE: object referenced only by a uintptr across the window. Its finalizer
	// SHOULD fire, proving the uintptr does not keep it alive (== UNSAFE if a C
	// call were in flight, since the object could be freed mid-write).
	naiveReclaimed := 0
	for i := 0; i < 2000; i++ {
		buf := new(int64)
		finalized := make(chan struct{})
		runtime.SetFinalizer(buf, func(*int64) { close(finalized) })
		laundered := uintptr(unsafe.Pointer(buf))
		buf = nil // drop typed ref — only the (GC-invisible) uintptr remains
		window()
		select {
		case <-finalized:
			naiveReclaimed++ // reclaimed while "in flight" — the hazard
		default:
		}
		runtime.KeepAlive(laundered) // uintptr KeepAlive is a no-op for liveness
	}

	// CONTROL: identical, but the typed pointer is KeepAlive'd across the window.
	// Its finalizer must NEVER fire during the window.
	controlReclaimed := 0
	for i := 0; i < 2000; i++ {
		buf := new(int64)
		finalized := make(chan struct{})
		runtime.SetFinalizer(buf, func(*int64) { close(finalized) })
		_ = uintptr(unsafe.Pointer(buf))
		window()
		select {
		case <-finalized:
			controlReclaimed++ // must stay 0
		default:
		}
		runtime.KeepAlive(buf) // typed KeepAlive: the liveness guard
	}

	if naiveReclaimed == 0 {
		t.Fatalf("probe inconclusive: 0/2000 laundered-only buffers were reclaimed mid-window; " +
			"expected the finalizer to fire without a typed ref (GC tuning issue in the probe)")
	}
	if controlReclaimed != 0 {
		t.Fatalf("control FAILED: %d/2000 KeepAlive'd buffers reclaimed mid-window; "+
			"KeepAlive(&obj) must keep the object alive across the call", controlReclaimed)
	}
	t.Logf("NAIVE path: %d/2000 laundered-only buffers reclaimed mid-window (UNSAFE); "+
		"KeepAlive control: 0/2000 reclaimed (KeepAlive covers liveness — movement needs Pinner, "+
		"see TestNoescapeProbe_KeepAliveOnlyUnsound)", naiveReclaimed)
}
